{
  "findings": [
    {
      "check_id": "CKV_AWS_227",
      "title": "Launch configuration is not configured to use an encrypted EBS volume",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not specify whether the EBS volume is encrypted, potentially exposing data at rest to unauthorized access."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"levelup-launchconfig\" {\n  name_prefix     = \"levelup-launchconfig\"\n  image_id        = lookup(var.AMIS, var.AWS_REGION)\n  instance_type   = \"t2.micro\"\n  key_name        = aws_key_pair.levelup_key.key_name\n  root_block_device {\n    encrypted = true\n  }\n}",
  "fix_summary": "Added root_block_device configuration with encrypted = true to ensure EBS volume encryption."
}
